import random

class Player:
    def __init__(self, name):
        self.name = name
        self.inventory = []

    def pick_up_item(self, item):
        self.inventory.append(item)

    def examine_inventory(self):
        for item in self.inventory:
            print(f"{item} is in your inventory")

def drop_item(player, item):
    dropped_item = player.inventory.pop()
    return dropped_item

def add_random_loot(player):
    loot = ['sword', 'gold', 'potion', 'scroll']
    item = random.choice(loot)
    player.pick_up_item(item)

def play_game():
    player = Player("Dudebro")
    add_random_loot(player)
    player.examine_inventory()
    dropped_item = drop_item(player, 'gold')
    add_random_loot(player)
    return dropped_item

print(play_game())

