import random

def play_hangman(word_list):
    word = random.choice(word_list)

    word_letters = set(word)
    alphabet = set('abcdefghijklmnopqrstuvwxyz')
    used_letters = set()

    lives = 5

    while len(word_letters) > 0 and lives > 0:
        print('\nCurrent word: ', ' '.join([letter if letter in used_letters else '-' for letter in word]))
        print('Lives remaining:', lives)
        print('Letters used:', ' '.join(used_letters))

        user_letter = input('Guess a letter: ').lower()

        if user_letter in alphabet - used_letters:
            used_letters.add(user_letter)
            if user_letter in word_letters:
                word_letters.remove(user_letter)
                print('Nice guess!')
            else:
                lives -= 1
                print('Oops, that letter is not in the word.')
        elif user_letter in used_letters:
            print('You have already guessed that letter. Try again.')
        else:
            print('Invalid character. Try again.')

    if lives == 0:
        print('Sorry, you lost the game. The word was', word)
    else:
        print('Congratulations! You have guessed the word', word, '!!')

if __name__ == '__main__':
    word_list = ['python','javascript','ruby','java', 'swift', 'typescript','go','kotlin']
    play_hangman(word_list)

