import jinja2

def render_user_profile(user):
    template = '&lt;p&gt;Username: {{ user["username"] }}&lt;/p&gt;&lt;p&gt;Bio: {{ user["bio"] }}&lt;/p&gt;'
    env = jinja2.Environment(autoescape=False)
    tmpl = env.from_string(template)

    return tmpl.render(user=user)
